/**
 * Experiment gate — decide whether this page load gets the SDK at all.
 *
 * A storefront running an A/B test on Omniguide has to answer one question
 * before `init()`: is this visitor in the arm that sees it? Until now every
 * store answered it in a hand-written `<script>` block, and every one of those
 * blocks was a fresh chance to get the failure modes wrong.
 *
 * ── The whole safety story: it FAILS OPEN ───────────────────────────
 *
 * Every path that is not an explicit "this visitor is in the control arm"
 * resolves to ENABLED. A flag service that is slow, absent, broken, blocked by
 * an ad blocker, or returning a shape nobody expected must never be able to
 * take the SDK off a storefront — an analytics outage is not a reason to stop
 * selling. The only two ways to end up disabled are an explicit local override
 * of `'off'` and a flag that resolved to a variant which is not `enabledWhen`.
 *
 * Each arm below is a distinct STRING rather than a boolean, and it is
 * registered as a PostHog super-property, so the experiment's own analysis can
 * tell "control" apart from "the flag never resolved" — which otherwise look
 * identical in the results and quietly poison them.
 *
 *   forced_on / forced_off   localStorage override (debug / QA escape hatch)
 *   no_experiment            no flagKey configured; everyone gets the SDK
 *   provider_unsupported     an experiment.provider this SDK does not know
 *   posthog_absent           window.posthog missing or not flag-capable
 *   flag_unresolved          the flag returned undefined / null
 *   flag_shape_unexpected    the flag returned something that is not a string
 *                            or a boolean
 *   flag_error               the lookup threw
 *   <variant>                the flag resolved to a string; that is the arm
 *   true / false             a BOOLEAN flag; `true` enables whatever
 *                            `enabledWhen` says, `false` is the control arm
 */

import { logger } from '@swiftotter/omniguide-core';

import { getPostHog, type PostHogLike } from './posthog.js';

export interface ExperimentConfig {
  /**
   * Flag provider. `'posthog'` is the only one implemented; anything else
   * fails open (the SDK runs) and logs once.
   */
  provider?: 'posthog';
  /**
   * The feature-flag / experiment key. `null` or absent means there is no
   * experiment at all and every visitor gets the SDK.
   */
  flagKey?: string | null;
  /** The variant value that means "show the SDK". Default `'test'`. */
  enabledWhen?: string;
  /** How long to wait for flags before deciding anyway. Default 2500ms. */
  timeoutMs?: number;
  /**
   * localStorage key holding a manual override: `'on'` or `'off'`. Anything
   * else is ignored. Default `'og_ab_force'`.
   */
  overrideKey?: string;
  /**
   * PostHog super-property the resolved arm is registered under, so every
   * event the visitor sends carries which arm they were in. Default
   * `'omniguide_ai_arm'`.
   */
  registerProperty?: string;
}

export interface ExperimentDecision {
  /** Whether this page load should initialise the SDK. */
  enabled: boolean;
  /** Which arm produced that verdict. Never empty. */
  arm: string;
}

export const EXPERIMENT_DEFAULTS = {
  provider: 'posthog' as const,
  enabledWhen: 'test',
  timeoutMs: 2500,
  overrideKey: 'og_ab_force',
  registerProperty: 'omniguide_ai_arm',
};

/**
 * One log line per page for an unsupported provider, not one per init().
 *
 * `init()` is callable more than once, and a misconfigured provider is a
 * permanent condition — repeating it turns a console the integrator needs to
 * read into noise.
 */
let unsupportedProviderWarned = false;

/** Test seam: forget the once-only log so the next test can observe it. */
export function _resetExperimentWarnings(): void {
  unsupportedProviderWarned = false;
}

/**
 * Read the manual override, or null.
 *
 * `localStorage` ACCESS — not just a miss — throws in Safari private mode and
 * under a blocked-storage policy, so the read is wrapped rather than the
 * parse. A throw means "no override", never "disabled".
 */
export function readForcedArm(overrideKey: string = EXPERIMENT_DEFAULTS.overrideKey): 'on' | 'off' | null {
  if (typeof window === 'undefined') return null;
  try {
    const value = window.localStorage.getItem(overrideKey);
    return value === 'on' || value === 'off' ? value : null;
  } catch {
    return null;
  }
}

/**
 * Call `callback` once flags are ready, or after `timeoutMs`, whichever comes
 * first — and EXACTLY once.
 *
 * The timeout is not a nicety. `onFeatureFlags` does not fire at all when the
 * flag request is blocked by an ad blocker or dropped by a network the shopper
 * is on, and without the fallback the SDK would simply never initialise on
 * those page loads: a silent, total outage on exactly the visitors whose
 * browsers are most locked down. PostHog may also fire `onFeatureFlags` again
 * on a later refresh, which is why the `done` latch is not optional either —
 * a second call would run `init()` twice.
 */
export function whenFlagsReady(
  callback: () => void,
  timeoutMs: number = EXPERIMENT_DEFAULTS.timeoutMs,
): void {
  // `getPostHog()` already catches a throwing `window.posthog` GETTER, but the
  // shape check below reads a property off the object it hands back, and that
  // read can throw too: a consent platform or privacy extension that replaces
  // `window.posthog` with a Proxy or an accessor stub raises on method access,
  // not on the window read. This was the one PostHog property access in the
  // file outside a `try`, and a throw here propagated out through
  // `resolveExperiment`'s promise executor — `start()` rejected, `init()` was
  // never called, and the SDK was absent from every page on that browser.
  //
  // `callback()` is deliberately OUTSIDE the try. Inside it, a callback that
  // threw would be caught here and invoked a second time — two `init()` calls,
  // which is the thing the `done` latch below exists to prevent.
  //
  // The METHOD is captured here, not re-read later: reading it twice gives a
  // hostile stub two chances to throw, and the second read is the one outside
  // this guard.
  let subscribe: PostHogLike['onFeatureFlags'] | null = null;
  try {
    const posthog = getPostHog();
    if (posthog && typeof posthog.onFeatureFlags === 'function') {
      subscribe = posthog.onFeatureFlags.bind(posthog);
    }
  } catch {
    subscribe = null;
  }
  if (!subscribe) {
    callback();
    return;
  }

  let done = false;
  let timer: ReturnType<typeof setTimeout> | null = null;
  const fire = (): void => {
    if (done) return;
    done = true;
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
    callback();
  };

  try {
    subscribe(fire);
  } catch {
    // A PostHog stub whose `onFeatureFlags` throws is still a PostHog that
    // will never call us back. Decide now; scheduling a timeout behind a
    // subscription that failed only delays the same answer.
    fire();
    return;
  }

  timer = setTimeout(fire, timeoutMs);
}

/**
 * Resolve the arm SYNCHRONOUSLY from whatever is on the page right now.
 *
 * Call it from inside `whenFlagsReady` (see `resolveExperiment`) — on its own
 * it will read flags that have not arrived yet and land on `flag_unresolved`.
 */
export function resolveExperimentArm(config: ExperimentConfig = {}): ExperimentDecision {
  // The override is checked FIRST, above the provider check, on purpose: it is
  // the escape hatch an engineer reaches for when the flag side is exactly
  // what is misconfigured. Gating it behind a working provider would disarm it
  // in the one situation it exists for.
  const forced = readForcedArm(config.overrideKey ?? EXPERIMENT_DEFAULTS.overrideKey);
  if (forced) return { enabled: forced === 'on', arm: `forced_${forced}` };

  const provider = config.provider ?? EXPERIMENT_DEFAULTS.provider;
  if (provider !== EXPERIMENT_DEFAULTS.provider) {
    if (!unsupportedProviderWarned) {
      unsupportedProviderWarned = true;
      logger.warn(
        `experiment.provider "${String(provider)}" is not supported; failing open and running the SDK for everyone.`,
      );
    }
    return { enabled: true, arm: 'provider_unsupported' };
  }

  if (!config.flagKey) return { enabled: true, arm: 'no_experiment' };

  try {
    const posthog = getPostHog();
    if (!posthog || typeof posthog.getFeatureFlag !== 'function') {
      return { enabled: true, arm: 'posthog_absent' };
    }
    const variant = posthog.getFeatureFlag(config.flagKey);
    if (variant === undefined || variant === null) {
      return { enabled: true, arm: 'flag_unresolved' };
    }
    // PostHog returns BOOLEANS for a boolean flag and strings only for a
    // multivariate one. `true` means "this visitor has the flag ON" — the
    // population the experiment exists to serve — and it is the single most
    // likely misconfiguration on go-live day: someone creates the key as a
    // boolean flag rather than a multivariate experiment with a `test`
    // variant, rolls it to 100%, and `true !== 'test'` turns the SDK OFF for
    // everyone it was just turned on for, under an arm reading `"true"` that
    // looks like a clean resolution in the PostHog breakdown.
    if (variant === true) return { enabled: true, arm: 'true' };
    // `false` stays DISABLED, and is the one non-string that does. It is not
    // an unexpected shape: it is PostHog's explicit "this visitor does not
    // have the flag", which is the boolean-flag spelling of the control arm.
    // Failing open on it would mean a boolean flag could never gate anyone,
    // which is the gate not working rather than the gate failing safe.
    if (variant === false) return { enabled: false, arm: 'false' };
    // Anything else — a number, an object, a Promise from a `getFeatureFlag`
    // someone wrapped in async — is a shape this SDK has no reading for, and
    // the module contract above says only an EXPLICIT control arm disables.
    // `String(variant)` on these produced arms like `"[object Promise]"`,
    // which disabled the SDK and recorded nonsense for the analysis.
    if (typeof variant !== 'string') {
      logger.warn(
        `feature flag "${config.flagKey}" resolved to a ${typeof variant}, not a string or boolean; `
        + 'failing open and running the SDK.',
      );
      return { enabled: true, arm: 'flag_shape_unexpected' };
    }
    return {
      enabled: variant === (config.enabledWhen ?? EXPERIMENT_DEFAULTS.enabledWhen),
      arm: variant,
    };
  } catch (error) {
    logger.warn('feature-flag lookup failed; failing open:', error);
    return { enabled: true, arm: 'flag_error' };
  }
}

/**
 * Publish the resolved arm as a PostHog super-property.
 *
 * Non-fatal by construction. This is bookkeeping for the experiment's own
 * analysis; if it fails the visitor should still get whatever arm they were
 * assigned, so every failure here is swallowed.
 */
export function registerExperimentArm(
  arm: string,
  registerProperty: string = EXPERIMENT_DEFAULTS.registerProperty,
): void {
  try {
    const posthog = getPostHog();
    if (posthog && typeof posthog.register === 'function') {
      posthog.register({ [registerProperty]: arm });
    }
  } catch {
    // Non-fatal: see above.
  }
}

/**
 * Wait for flags if there is anything to wait for, then resolve the arm.
 *
 * The wait is SKIPPED when no `flagKey` is configured. Without that, a store
 * that carries an `experiment` block only to set `overrideKey` — or one that
 * has finished its test and set `flagKey: null` — would pay up to `timeoutMs`
 * of delayed initialisation on every page load to answer a question with no
 * flag in it. The arm it would reach after waiting is identical.
 */
export function resolveExperiment(config?: ExperimentConfig): Promise<ExperimentDecision> {
  if (!config?.flagKey) return Promise.resolve(resolveExperimentArm(config));
  return new Promise<ExperimentDecision>(resolve => {
    whenFlagsReady(
      () => { resolve(resolveExperimentArm(config)); },
      config.timeoutMs ?? EXPERIMENT_DEFAULTS.timeoutMs,
    );
  });
}
