/**
 * Config values the SDK can work out for itself.
 *
 * Both of these were hand-written in the storefront's `<script>` block, and
 * both were a FACT THE CONFIG ALREADY STATED, restated in JavaScript:
 *
 *   categoryUrl: window.location.pathname.replace(/\.html$/, ''),
 *   ui: { urlSuffix: '.html' }
 *
 * Two lines, one fact, two places to change it — and when they disagree the
 * symptom is a category guide that asks the backend about a path it does not
 * index, which looks like a backend problem.
 *
 * Deliberately free of heavy imports so either bundle entry can use it without
 * dragging the platform adapters along.
 */

import type { BundleInitConfig } from './types.js';

/**
 * The product SKU, from config or from the page.
 *
 * Returns `undefined` — never `''`. An empty string is a SKU as far as every
 * downstream `if (sku)` is concerned right up until it reaches the API, where
 * it becomes a lookup for a product that does not exist.
 */
export function resolveProductSku(userConfig: BundleInitConfig): string | undefined {
  if (userConfig.productSku) return userConfig.productSku;

  const selector = userConfig.productSkuSelector;
  if (!selector || typeof document === 'undefined') return undefined;

  let text: string | null | undefined;
  try {
    text = document.querySelector(selector)?.textContent;
  } catch {
    // An invalid selector throws rather than returning null. A typo in a
    // config string must not take the SDK down.
    return undefined;
  }

  const trimmed = text?.trim();
  return trimmed ? trimmed : undefined;
}

/**
 * Whether the product-fit feature applies to THIS page.
 *
 * Only meaningful when `productSkuSelector` is configured: the selector is the
 * store's own answer to "is this a product page?", and on a store that set one,
 * no SKU on the page means no product to fit. Without a selector this always
 * returns true and the store's `features.productFit` stands unchanged — that
 * is the existing behaviour every other integration relies on.
 *
 * Note this can overrule an explicit `features.productFit: true`. That is the
 * intent: the storefront previously wrote `productFit: !!productSku` by hand,
 * and moving the SKU lookup into the SDK without moving that gate with it would
 * have left product fit mounting on every category and cart page.
 */
export function productFitApplies(userConfig: BundleInitConfig): boolean {
  return productFitSuppressionReason(userConfig) === null;
}

/**
 * Why product fit is being forced off for this page, or `null`.
 *
 * Turning a feature off is the one thing this module does that a store can
 * neither see nor undo, and it did it silently. A store that sets
 * `productSkuSelector` and calls `init()` directly — the supported synchronous
 * path — on a PDP whose SKU block the theme renders AFTER `init()` runs gets
 * `productFit: false` baked in for the life of the page, with no retry and no
 * console line. Product fit simply never appears and the on-call engineer has
 * nothing to go on.
 *
 * The message lives here, beside the decision, rather than at the two call
 * sites: the UMD entry logs through core's `logger` and the ESM loader through
 * `console`, and a message written twice is a message that drifts.
 */
export function productFitSuppressionReason(userConfig: BundleInitConfig): string | null {
  const selector = userConfig.productSkuSelector;
  if (!selector) return null;
  if (resolveProductSku(userConfig) !== undefined) return null;
  return `product fit is OFF for this page: productSkuSelector "${selector}" matched no SKU. `
    + 'If this is a product page, the SKU element is probably rendered after init() runs — '
    + 'use Omniguide.start(), which waits for DOMContentLoaded, or pass productSku directly.';
}

/**
 * The category URL the backend should be asked about — or `undefined`.
 *
 * Defaults to the current pathname with `ui.urlSuffix` stripped. The backend
 * indexes suffix-free paths (that is what `ui.urlSuffix` exists for on the
 * link-building side), so on a `.html` storefront the un-stripped pathname
 * misses every category.
 *
 * It resolves a value ONLY when there is a suffix to strip, and returns
 * `undefined` otherwise, on purpose. `undefined` is not "no answer": core's
 * `questions.ts` already reads `categoryUrl ?? window.location.pathname`, and
 * it reads it when the question is ASKED rather than when `init()` ran.
 * Returning an eager pathname here for every store would replace that late
 * read with an early one — identical on a server-rendered storefront, and
 * stale on anything that changes the path without a reload. So this narrows
 * itself to the one case the lazy default gets wrong.
 */
export function resolveCategoryUrl(userConfig: BundleInitConfig): string | undefined {
  if (userConfig.categoryUrl !== undefined) return userConfig.categoryUrl;

  const suffix = userConfig.ui?.urlSuffix;
  if (!suffix) return undefined;
  if (typeof window === 'undefined') return undefined;

  const pathname = window.location?.pathname;
  if (typeof pathname !== 'string') return undefined;

  // `pathname !== suffix` keeps a pathological `/.html` from resolving to the
  // empty string, which reads downstream as "not configured".
  if (pathname !== suffix && pathname.endsWith(suffix)) {
    return pathname.slice(0, -suffix.length);
  }
  return undefined;
}
