/**
 * `Omniguide.start(config)` — the one call a storefront makes.
 *
 * `init()` is unchanged and stays the public, synchronous API other stores
 * already call. `start()` is the wrapper around it that every A/B-tested
 * storefront had been writing by hand:
 *
 *   wait for DOMContentLoaded
 *     → resolve the experiment arm
 *       → register the arm on the analytics identity
 *         → init(), or don't
 *
 * It resolves to the instance, or to `null` when the visitor is in an arm that
 * should not see the SDK. `null` is a verdict, not a failure — callers that
 * want the instance should check for it rather than assume.
 */

import { logger } from '@swiftotter/omniguide-core';

import { resolveExperiment, registerExperimentArm } from './experiment.js';
import type { BundleInitConfig, OmniguideInstance } from './types.js';

/**
 * Resolve once the DOM is parsed.
 *
 * Everything the SDK mounts is selector-driven — the search trigger, the PDP
 * and PLP mount targets, and now `productSkuSelector`. Running before
 * `DOMContentLoaded` finds none of them and degrades to an SDK that loads and
 * then does nothing visible, which is the hardest kind of integration bug to
 * see. `{ once: true }` so a listener is not left behind on a page that calls
 * `start()` more than once.
 */
function domReady(): Promise<void> {
  if (typeof document === 'undefined') return Promise.resolve();
  if (document.readyState !== 'loading') return Promise.resolve();
  return new Promise<void>(resolve => {
    document.addEventListener('DOMContentLoaded', () => { resolve(); }, { once: true });
  });
}

/**
 * Warn if the SDK global is missing — the guard the page used to carry.
 *
 * The storefront's version RETURNED here, because without `window.Omniguide`
 * it had nothing to call. This one only warns and carries on: `start()` holds
 * a direct reference to `init`, so a missing global means the UMD wrapper did
 * not publish (an ESM import, a script-tag ordering problem, a CSP rule) —
 * worth saying out loud, never a reason to refuse to initialise.
 */
function warnIfGlobalMissing(): void {
  if (typeof window === 'undefined') return;
  const global = (window as unknown as Record<string, unknown>)['Omniguide'] as
    | Record<string, unknown>
    | undefined;
  if (!global || typeof global['init'] !== 'function') {
    logger.warn(
      'window.Omniguide.init is not present. The SDK is starting from a direct module reference; '
      + 'check the CDN script tag if you expected the global.',
    );
  }
}

/**
 * Build a `start` bound to a particular `init`.
 *
 * A factory rather than a direct import, because the bundle has two entries —
 * the UMD build's eager `init` and the ESM loader's lazy one — and `start()`
 * has to mean the same thing on both without either entry importing the other.
 */
export function createStart(
  init: (config: BundleInitConfig) => OmniguideInstance,
): (config: BundleInitConfig) => Promise<OmniguideInstance | null> {
  return async function start(config: BundleInitConfig): Promise<OmniguideInstance | null> {
    // The WHOLE gate is inside one try, and every exit from the catch falls
    // through to `init(config)`.
    //
    // The gate's job is to answer one question about analytics, and the module
    // it calls is written to fail open at every branch — but "fails open" has
    // to include the branches nobody enumerated. A throwing `window.posthog`
    // stub (a consent platform, a privacy extension) escaped through
    // `resolveExperiment`'s promise executor and REJECTED this promise: the
    // documented usage is `Omniguide.start({...})` with no `.catch()`, so the
    // storefront got no SDK, no error anyone would see, and an unhandled
    // rejection. `start()` must not be able to reject for anything the gate
    // does.
    //
    // `init(config)` is deliberately OUTSIDE the try. It throws on a missing
    // `websiteId`, and that is a config error the integrator has to see —
    // swallowing it would turn a loud, fixable mistake into an SDK that loads
    // and silently does nothing, which is the failure this file exists to stop.
    try {
      await domReady();
      warnIfGlobalMissing();

      const decision = await resolveExperiment(config.experiment);
      registerExperimentArm(decision.arm, config.experiment?.registerProperty);

      if (!decision.enabled) {
        // `warn`, not `debug`: core's logger suppresses debug in production
        // unless `localStorage['ai-debug']` is set, so the control arm — the
        // one case where the SDK deliberately does nothing — left a COMPLETELY
        // silent console. On a go-live that is indistinguishable from a 404 on
        // the script, a CSP block, or a UMD failure, and it is the single
        // most-asked question of an A/B launch. The super-property is the
        // intended answer and it only exists if PostHog loaded, which is
        // exactly what is in doubt when someone is asking.
        logger.warn(
          `Omniguide is not initialising: experiment arm "${decision.arm}" is not the enabled arm. `
          + `Set localStorage["${config.experiment?.overrideKey ?? 'og_ab_force'}"] = "on" to override.`,
        );
        return null;
      }
    } catch (error) {
      logger.warn('the experiment gate failed; initialising anyway (fail open):', error);
    }

    return init(config);
  };
}
