/**
 * Analytics adapter presets.
 *
 * `analyticsAdapter` is the SDK's one analytics seam: the SDK calls `track()`
 * and the host decides where it goes. That is the right shape, but it meant
 * every PostHog storefront hand-wrote the same six-line adapter into its
 * theme — and the one line that actually matters in those six, the try/catch,
 * is the one easiest to leave out.
 *
 * `analytics: { posthog: true }` is that adapter, shipped.
 */

import type { AnalyticsAdapter } from '@swiftotter/omniguide-core';

import { getPostHog } from './posthog.js';

export interface AnalyticsPresetConfig {
  /** Send SDK events to `window.posthog.capture`, if PostHog is present. */
  posthog?: boolean;
}

/**
 * An adapter that forwards to `window.posthog.capture` and NEVER throws.
 *
 * Analytics must not be able to break a storefront. `track()` is called from
 * inside render paths and event handlers all over the SDK, so an exception
 * escaping it does not lose a metric — it takes down whatever was rendering.
 * PostHog is read per call rather than captured once, because the storefront's
 * snippet may swap its stub for the real library after the SDK initialises.
 */
export function createPostHogAnalyticsAdapter(): AnalyticsAdapter {
  return {
    track(eventName: string, properties?: Record<string, unknown>): void {
      try {
        const posthog = getPostHog();
        if (posthog && typeof posthog.capture === 'function') {
          posthog.capture(eventName, properties ?? {});
        }
      } catch {
        // Never let analytics break the page.
      }
    },
  };
}

/**
 * Pick the adapter for a config.
 *
 * An EXPLICIT `analyticsAdapter` always wins over the `analytics` preset. The
 * preset is a convenience for the common case; a store that hands the SDK its
 * own adapter has, by definition, a destination the preset does not know
 * about, and silently replacing it would be the SDK overruling the integrator.
 * A store passing both gets its own adapter, with no warning — the preset flag
 * is then simply redundant, not a conflict.
 */
export function resolveAnalyticsAdapter(userConfig: {
  analyticsAdapter?: AnalyticsAdapter;
  analytics?: AnalyticsPresetConfig;
}): AnalyticsAdapter | undefined {
  if (userConfig.analyticsAdapter) return userConfig.analyticsAdapter;
  if (userConfig.analytics?.posthog) return createPostHogAnalyticsAdapter();
  return undefined;
}
