/**
 * DOM mounting utilities for Omniguide widgets.
 *
 * Shared by BCProductFitIntegration, BCCategoryGuideIntegration,
 * StencilIntegration, and the ESM loader.
 */

import { createScopedLogger } from './logger.js';

const log = createScopedLogger('resolveContainer');

// ── Types ──────────────────────────────────────────────────────────

export type MountPosition = 'before' | 'after' | 'inside' | 'replace';

export interface MountTarget {
  /** CSS selector or HTMLElement to mount relative to */
  target: string | HTMLElement;
  /** Position relative to the target element (default: 'inside') */
  position?: MountPosition;
}

/**
 * Where a widget mounts: one target, or an ordered list of fallbacks.
 *
 * A list exists because one storefront template is rarely one page shape. On
 * Magento, for example, a standard category page has `.page-title-wrapper` and
 * a product-line landing page does not — the guide belongs on both, anchored to
 * a different element on each, and on opposite sides of it.
 *
 * A comma-separated CSS selector cannot express that: it gives every branch the
 * same `position`, and `querySelector` resolves by DOCUMENT order, so which
 * branch wins on a page where several match is a property of the markup rather
 * than of the config. A list is resolved in ARRAY order and each entry carries
 * its own position, so the intent is explicit and stable.
 */
export type MountSpec = MountTarget | MountTarget[];

// ── resolveContainer ───────────────────────────────────────────────

/**
 * Marks a container this module created, so a repeat resolve reuses it rather
 * than stacking a new empty <div> beside the target on every init().
 */
const CONTAINER_ATTR = 'data-omniguide-container';


/** Resolve one target. Returns null WITHOUT touching the DOM if it is absent. */
function resolveOne(mount: MountTarget | null | undefined): HTMLElement | null {
  if (!mount?.target) {
    return null;
  }

  let target: HTMLElement | null;
  if (mount.target instanceof HTMLElement) {
    target = mount.target;
  } else {
    try {
      target = document.querySelector<HTMLElement>(mount.target);
    } catch {
      // `querySelector` throws SyntaxError on a malformed selector. In a
      // fallback list that would take out every entry AFTER the bad one, so a
      // single typo silently disables the mount points that were meant to
      // cover the other page shapes. Skip this entry and keep going — loudly:
      // the caller reports the whole list when nothing matches, and a bad
      // selector shows up there rather than as a bare SyntaxError.
      log.warn(`Ignoring malformed mount selector: ${String(mount.target)}`);
      return null;
    }
  }

  if (!target) {
    return null;
  }

  const position = mount.position ?? 'inside';

  // 'inside' means render directly inside the target (no new container needed)
  if (position === 'inside') {
    return target;
  }

  // Everything below positions a container as a SIBLING of the target, which
  // needs a parent. A detached target (a stale reference the theme has since
  // replaced) would otherwise no-op the insert and still hand back a floating
  // <div>: the widget renders into a node that is in no document, init()
  // reports success, and the page stays empty. Report no match instead, so the
  // next entry in the list gets its turn.
  if (!target.parentNode) {
    log.warn(
      `Mount target is detached from the document (position: ${position}). Skipping it.`,
    );
    return null;
  }

  // 'replace' means swap the target with a new container
  if (position === 'replace') {
    const container = document.createElement('div');
    target.replaceWith(container);
    return container;
  }

  // 'before' or 'after' — create a sibling container.
  //
  // Reuse the one we made last time if it is still there. resolveContainer runs
  // again on every host init() — an AJAX layered-nav update, a variant change —
  // and a fresh node each time would orphan an empty <div> per call AND defeat
  // the integrations' identity-based double-mount guard, tearing the live React
  // root down and rebuilding it (a visible flash, questionnaire answers lost).
  const sibling = position === 'before' ? target.previousElementSibling : target.nextElementSibling;
  if (sibling instanceof HTMLElement && sibling.hasAttribute(CONTAINER_ATTR)) {
    return sibling;
  }

  const container = document.createElement('div');
  container.setAttribute(CONTAINER_ATTR, '');
  if (position === 'before') {
    target.parentNode.insertBefore(container, target);
  } else {
    // 'after'
    target.parentNode.insertBefore(container, target.nextSibling);
  }

  return container;
}

/**
 * Resolve or create a container element for mounting a widget.
 *
 * Priority:
 * 1. If `mount` has entries, use the first target that EXISTS on the page, in
 *    the order given, and position a container relative to it. A single object
 *    is treated as a one-entry list, so existing callers are unaffected.
 * 2. If `mount` is absent or an empty list, fall back to
 *    `document.getElementById(defaultId)`.
 *
 * Entries whose target is absent or detached are skipped without touching the
 * DOM, so a `replace` that never matches cannot remove anything. A `before` or
 * `after` container is reused across calls rather than recreated.
 *
 * @returns The container HTMLElement to render into, or `null` if no target matched.
 */
export function resolveContainer(
  mount: MountSpec | undefined,
  defaultId: string,
): HTMLElement | null {
  // Fallback: look for the default container by ID. An EMPTY list takes this
  // path too — a list built by filtering page-type rules can legitimately come
  // out empty, and "no entries" means the same thing as "no mount key" rather
  // than "refuse to mount somewhere the page already provides".
  const entries = mount ? (Array.isArray(mount) ? mount : [mount]) : [];
  if (entries.length === 0) {
    return document.getElementById(defaultId);
  }

  for (const candidate of entries) {
    const container = resolveOne(candidate);
    if (container) {
      return container;
    }
  }

  return null;
}

/**
 * What `resolveContainer` would have tried, in order — for mount-failure diagnostics.
 *
 * Mirrors resolveContainer's own priority, so a spec with no entries reports the
 * `defaultId` it actually fell back to rather than an empty string.
 *
 * Tolerates the same malformed input `resolveOne` skips, because this is what
 * runs when a mount has already gone wrong: throwing here would replace the
 * message explaining the failure with a second, less useful failure.
 */
export function describeMountTargets(mount: MountSpec | undefined, defaultId: string): string {
  const entries = mount ? (Array.isArray(mount) ? mount : [mount]) : [];
  if (entries.length === 0) return `#${defaultId} (default)`;
  return entries
    .map((m) => {
      if (!m?.target) return '(invalid entry)';
      const target = m.target instanceof HTMLElement ? '<HTMLElement>' : m.target;
      return `${target} (${m.position ?? 'inside'})`;
    })
    .join(', ');
}
