/**
 * ESM Loader — Lightweight entry point for Omniguide AI SDK.
 *
 * ~3-5 KB gzipped. No React, no omniguide-core/react/bigcommerce at load time.
 * Features load on demand via dynamic import() — Vite code-splits automatically.
 *
 * Usage:
 *   <script type="module" src="omniguide-sdk.esm.js"></script>
 *   <script nomodule src="omniguide-sdk.standalone.js"></script>
 *   <link rel="stylesheet" href="omniguide-tokens.css">
 *   <script>
 *     Omniguide.init({ websiteId: 'https://mystore.com/' });
 *   </script>
 */

import { setupSearchTrigger, type SearchTriggerResult } from './search-trigger.js';
import { loadCss, prefetchCss, ensureReact } from './load-utils.js';
import { productFitApplies, productFitSuppressionReason } from './config-resolvers.js';
import { resolveAnalyticsAdapter } from './analytics-preset.js';
import { startEcommerceAnalytics } from './ecommerce-analytics.js';
import { createStart } from './start.js';
import type { BundleInitConfig, OmniguideInstance } from './types.js';
import type { SearchIntegration, FeatureIntegration, MountSpec, MountTarget } from '@swiftotter/omniguide-core';
import {
  describeMountTargets,
  initPreviewFromQueryParam,
  setPreviewApiUrl,
  clearPreviewApiUrl,
  isPreviewMode,
  // Tree-shaken down to a few bytes of module state, so the loader stays light.
  // It must come from core rather than the feature chunks: the hook that records
  // health runs inside a lazily imported chunk, and only a module both sides
  // share reports what that hook actually saw.
  getAnalyticsAdapterHealth,
} from '@swiftotter/omniguide-core';

// Check query param override before any init() call
initPreviewFromQueryParam();

declare const __OMNIGUIDE_VERSION__: string;

// ── Asset URL resolution ─────────────────────────────────────────

/**
 * Resolve the base URL for loading sibling CSS assets.
 * Uses import.meta.url to determine where the loader was loaded from.
 */
function resolveBase(): string {
  try {
    const url = new URL(import.meta.url);
    return url.href.substring(0, url.href.lastIndexOf('/') + 1);
  } catch {
    return './';
  }
}

// ── Dynamic import factories (Vite code-splits these) ────────────

// These static dynamic imports let Vite analyze the dependency graph
// and create proper code-split chunks for each feature.
const loadSearchModule = () => import('./features/search.js');
const loadProductFitModule = () => import('./features/product-fit.js');
const loadCategoryGuideModule = () => import('./features/category-guide.js');

// ── CSS asset names (predictable, no hashes) ─────────────────────

const CSS_ASSETS = {
  tokens: 'omniguide-tokens.css',
  search: 'omniguide-search.css',
  productFit: 'omniguide-product-fit.css',
  categoryGuide: 'omniguide-category-guide.css',
} as const;

// ── State ────────────────────────────────────────────────────────

let currentConfig: BundleInitConfig | null = null;
let searchIntegration: SearchIntegration | null = null;
 
let searchChunkPromise: Promise<any> | null = null;
let triggerResult: SearchTriggerResult | null = null;
let productFitIntegration: FeatureIntegration | null = null;
let categoryGuideIntegration: FeatureIntegration | null = null;

// ── Micro-spinner ────────────────────────────────────────────────

const SPINNER_ID = 'omniguide-loading-spinner';

function showSearchSpinner(): void {
  if (document.getElementById(SPINNER_ID)) return;
  const overlay = document.createElement('div');
  overlay.id = SPINNER_ID;
  overlay.style.cssText = `
    position:fixed;top:0;left:0;right:0;bottom:0;
    z-index:10001;
    display:flex;align-items:center;justify-content:center;
    background:rgba(0,0,0,0.3);
  `;
  overlay.innerHTML = `
    <div style="
      width:40px;height:40px;
      border:3px solid rgba(255,255,255,0.3);
      border-top-color:#fff;
      border-radius:50%;
      animation:omniguide-spin 0.8s linear infinite;
    "></div>
    <style>@keyframes omniguide-spin{to{transform:rotate(360deg)}}</style>
  `;
  document.body.appendChild(overlay);
}

function hideSearchSpinner(): void {
  document.getElementById(SPINNER_ID)?.remove();
}

// ── Visibility observer ──────────────────────────────────────────

function observeVisibility(el: Element, rootMargin: string, onVisible: () => void): IntersectionObserver {
  const io = new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        if (entry.isIntersecting) {
          io.disconnect();
          onVisible();
          return;
        }
      }
    },
    { rootMargin },
  );
  io.observe(el);
  return io;
}

// ── Search lazy loading ──────────────────────────────────────────

function getSearchChunk() {
  if (!searchChunkPromise) {
    searchChunkPromise = loadSearchModule();
  }
  return searchChunkPromise;
}

async function handleOpenSearch(query: string, source: string, base: string): Promise<void> {
  if (searchIntegration) {
    searchIntegration.openSearch(query, source);
    return;
  }

  // Show micro-spinner if loading takes >150ms
  const spinnerTimeout = window.setTimeout(() => showSearchSpinner(), 150);

  try {
    const [mod] = await Promise.all([
      getSearchChunk(),
      loadCss(base + CSS_ASSETS.search),
      ensureReact(),
    ]);

    clearTimeout(spinnerTimeout);
    hideSearchSpinner();

    const omniguideConfig = mod.buildConfig(currentConfig);
    const platformAdapter = mod.buildPlatformAdapter(currentConfig);
    const integration = new mod.BCSearchIntegration({
      config: omniguideConfig,
      platformAdapter,
      skipDomSetup: true,
    });
    searchIntegration = integration;
    integration.init();
    integration.openSearch(query, source);

    // Invoke search.onOpen callback if provided
    currentConfig?.search?.onOpen?.(source);
  } catch (e) {
    clearTimeout(spinnerTimeout);
    hideSearchSpinner();
    // eslint-disable-next-line no-console -- surface dynamic-import failure at top-level loader
    console.error('[Omniguide] Failed to load search:', e);
  }
}

// ── PDP/PLP lazy mounting ────────────────────────────────────────

async function mountProductFit(config: BundleInitConfig, base: string): Promise<void> {
  try {
    const [mod] = await Promise.all([
      loadProductFitModule(),
      loadCss(base + CSS_ASSETS.productFit),
      ensureReact(),
    ]);
    const omniguideConfig = mod.buildConfig(config);
    const platformAdapter = mod.buildPlatformAdapter(config);
    productFitIntegration = new mod.BCProductFitIntegration({
      config: omniguideConfig,
      platformAdapter,
      mount: config.pdpWidget?.mount,
    });
    productFitIntegration.init();
  } catch (e) {
    // eslint-disable-next-line no-console -- surface dynamic-import failure at top-level loader
    console.error('[Omniguide] Failed to load product fit:', e);
  }
}

async function mountCategoryGuide(config: BundleInitConfig, base: string): Promise<void> {
  try {
    const [mod] = await Promise.all([
      loadCategoryGuideModule(),
      loadCss(base + CSS_ASSETS.categoryGuide),
      ensureReact(),
    ]);
    const omniguideConfig = mod.buildConfig(config);
    const platformAdapter = mod.buildPlatformAdapter(config);
    categoryGuideIntegration = new mod.BCCategoryGuideIntegration({
      config: omniguideConfig,
      platformAdapter,
      mount: config.plpWidget?.mount,
    });
    categoryGuideIntegration.init();
  } catch (e) {
    // eslint-disable-next-line no-console -- surface dynamic-import failure at top-level loader
    console.error('[Omniguide] Failed to load category guide:', e);
  }
}

// ── CSS token injection ──────────────────────────────────────────

function injectTokenOverrides(tokens: Record<string, string>): void {
  const style = document.createElement('style');
  style.id = 'omniguide-token-overrides';
  const props = Object.entries(tokens)
    .map(([key, value]) => {
      const prop = key.startsWith('--') ? key : `--${key}`;
      return `  ${prop}: ${value};`;
    })
    .join('\n');
  style.textContent = `:root {\n${props}\n}`;
  document.head.appendChild(style);
}

// ── Observation target resolution ─────────────────────────────────

/**
 * Determine which element to observe for IntersectionObserver visibility-loading.
 * When a `mount` config is provided, the observation target is the mount target itself
 * (since the actual container doesn't exist yet — it's created at mount time).
 */
export function resolveObserveTarget(
  mount: MountSpec | undefined,
  selector: string | undefined,
  defaultSelector: string,
): Element | null {
  // Mirror resolveContainer exactly, or the two disagree about whether the page
  // is mountable: a list is tried in ARRAY order, the first target that EXISTS
  // wins, and an empty list means "nothing configured" rather than "nowhere".
  // Observing only the first entry would mean that on a page shape matched by a
  // LATER entry nothing is ever observed — the lazy mount never fires and the
  // widget silently never initialises: no container, no "no mount target"
  // warning, nothing.
  const entries = mountEntries(mount);
  for (const entry of entries) {
    if (!entry?.target) continue;
    if (entry.target instanceof HTMLElement) return entry.target;
    try {
      const found = document.querySelector(entry.target);
      if (found) return found;
    } catch {
      // Malformed selector — skip it rather than taking out the rest of the
      // list. resolveContainer warns about the same entry at mount time.
      continue;
    }
  }
  if (entries.length > 0) return null;
  return document.querySelector(selector ?? defaultSelector);
}

function mountEntries(mount: MountSpec | undefined): MountTarget[] {
  if (!mount) return [];
  return Array.isArray(mount) ? mount : [mount];
}

/** What `resolveObserveTarget` looked for — for the "nothing to observe" warning. */
function describeObserveTarget(
  mount: MountSpec | undefined,
  selector: string | undefined,
  defaultSelector: string,
): string {
  // The defaultId argument is unreachable here: describeMountTargets only uses
  // it when the spec has no entries, and that case takes the selector path.
  if (mountEntries(mount).length > 0) return describeMountTargets(mount, '');
  return selector ?? defaultSelector;
}

// ── Main init ────────────────────────────────────────────────────

/**
 * Start the dataLayer bridge once per init, if the storefront asked for it.
 *
 * Page level, not widget level. The loader mounts the PDP and PLP chunks only
 * when their target element exists (and by default only when it scrolls into
 * view), and search only when it is opened — so a cart or checkout page mounts
 * NOTHING. Those are exactly the pages where `dl_begin_checkout` and
 * `dl_purchase` fire, so a bridge started from a mounted provider never ran
 * where it mattered most.
 *
 * Dynamically imported, and only when configured: the loader's whole job is to
 * stay a few KB with no core at load time, and the bridge is off by default.
 * Start-up order does not matter — the bridge forwards nothing until an
 * EventService registers and then replays the whole array, so arriving a chunk
 * fetch late costs no events.
 *
 * The same import creates the page's EventService. The bridge needs somewhere
 * to deliver, and on these pages nothing else will ever build one — that is
 * the whole defect: the bridge ran page-level while its sink was built by a
 * React provider that never mounted here.
 */
function startBridgeIfConfigured(config: BundleInitConfig): void {
  const bridge = config.dataLayerBridge;
  if (!bridge) return;
  void import('@swiftotter/omniguide-core')
    .then((mod) => {
      // Re-checked against the bridge's own rule now that core is here: the
      // cheap check above only told us an object was passed, and `{}` or
      // `{gtm: false}` means off. Building a sink for those would leave a
      // flush interval and unload listeners on a storefront that said no.
      if (!mod.isDataLayerBridgeEnabled(bridge)) return;
      // Separately contained, so a sink that cannot be built — an unknown
      // consent reader in the theme's config, say — still leaves a bridge
      // running. It holds its backlog and replays it if a provider turns up.
      try {
        mod.ensurePageEventService({
          apiBaseUrl: mod.getApiBaseUrl(config.apiBaseUrl),
          websiteId: config.websiteId,
          consent: config.consent,
          sessionStorageKey: config.storageKeys?.sessionId,
        });
      } catch (error) {
        // eslint-disable-next-line no-console -- the loader has no logger of its own
        console.error('[Omniguide] Could not create the page EventService:', error);
      }
      mod.startDataLayerBridge(bridge);
    })
    .catch(() => {
      // Analytics forwarding is not worth taking the storefront down for.
    });
}

/**
 * Start the GA4 → analytics-adapter forwarder, page level.
 *
 * Page level for the same reason the bridge is: `begin_checkout` and
 * `purchase` fire on pages where no widget mounts. Unlike the bridge this
 * needs no lazy core import — `ecommerce-analytics.ts` pulls only the marker
 * and the logger, both of which the loader already imports.
 */
function startEcommerceAnalyticsIfConfigured(config: BundleInitConfig): void {
  if (!config.ecommerceAnalytics) return;
  const adapter = resolveAnalyticsAdapter(config);
  if (!adapter) {
    // eslint-disable-next-line no-console -- the loader has no logger of its own
    console.warn('[Omniguide] ecommerceAnalytics is configured but no analytics adapter is.');
    return;
  }
  try {
    startEcommerceAnalytics(adapter, config.ecommerceAnalytics, config.websiteId);
  } catch (e) {
    // eslint-disable-next-line no-console -- the loader has no logger of its own
    console.error('[Omniguide] Could not start the eCommerce analytics forwarder:', e);
  }
}

export function init(config: BundleInitConfig): OmniguideInstance {
  if (!config.websiteId) {
    throw new Error('[Omniguide] websiteId is required in config');
  }

  startBridgeIfConfigured(config);
  startEcommerceAnalyticsIfConfigured(config);

  // Mirrors buildConfig: the one branch that takes a feature away must say so.
  const productFitOff = productFitSuppressionReason(config);
  if (productFitOff) {
    // eslint-disable-next-line no-console -- the loader has no logger of its own
    console.warn('[Omniguide]', productFitOff);
  }

  currentConfig = config;
  const base = resolveBase();
  const features = {
    search: true,
    productFit: true,
    categoryGuide: true,
    ...config.features,
    // Mirrors buildConfig: a configured `productSkuSelector` that matches
    // nothing means this page has no product to fit. Kept in step with the
    // UMD entry so an integration does not behave differently per build.
    ...(productFitApplies(config) ? {} : { productFit: false }),
  };

  // Inject custom token overrides if provided
  if (config.tokens) {
    injectTokenOverrides(config.tokens);
  }

  // 1. Load tokens CSS immediately (tiny, ~3 KB)
  loadCss(base + CSS_ASSETS.tokens);

  // 2. Search trigger setup (sync DOM, no React)
  if (features.search && config.search?.replace !== null) {
    triggerResult = setupSearchTrigger(
      {
        replace: config.search?.replace,
        renderTrigger: config.search?.renderTrigger,
        icon: config.search?.icon,
        selectors: config.selectors,
        websiteId: config.websiteId,
        ui: config.ui,
      },
      (query, source) => handleOpenSearch(query, source, base),
    );

    // Intent-based prefetch
    const loadMode = config.search?.loadMode ?? 'intent';
    if (loadMode === 'intent' && triggerResult) {
      triggerResult.addIntentListeners(() => {
        // Prefetch search JS chunk (triggers modulepreload)
        getSearchChunk();
        // Prefetch search CSS
        prefetchCss(base + CSS_ASSETS.search);
      });
    } else if (loadMode === 'idle') {
      const schedule = window.requestIdleCallback ?? ((cb: IdleRequestCallback) => window.setTimeout(cb, 2000));
      schedule(() => {
        getSearchChunk();
        prefetchCss(base + CSS_ASSETS.search);
      });
    }
    // 'click' = no prefetch, load on demand
  }

  // Track IntersectionObservers for cleanup
  const observers: IntersectionObserver[] = [];

  // 3. PDP widget — IntersectionObserver
  if (features.productFit) {
    const pdpObserveEl = resolveObserveTarget(config.pdpWidget?.mount, config.pdpWidget?.selector, '[data-omniguide-pdp], #product-recommendations-root');
    if (!pdpObserveEl) {
      // Nothing to observe means the widget never loads. Silently skipping it
      // here is indistinguishable from `features.productFit` being off.
      // eslint-disable-next-line no-console -- mount misconfiguration must reach the integrator
      console.warn(`[Omniguide] Product fit: nothing to observe. Tried: ${describeObserveTarget(config.pdpWidget?.mount, config.pdpWidget?.selector, '[data-omniguide-pdp], #product-recommendations-root')}. Not loading.`);
    }
    if (pdpObserveEl) {
      const loadMode = config.pdpWidget?.loadMode ?? 'visible';
      if (loadMode === 'immediate') {
        mountProductFit(config, base);
      } else {
        const io = observeVisibility(pdpObserveEl, config.pdpWidget?.rootMargin ?? '600px', () => {
          mountProductFit(config, base);
        });
        observers.push(io);
      }
    }
  }

  // 4. PLP widget — IntersectionObserver
  if (features.categoryGuide) {
    const plpObserveEl = resolveObserveTarget(config.plpWidget?.mount, config.plpWidget?.selector, '[data-omniguide-plp], #category-recommendations-root');
    if (!plpObserveEl) {
      // eslint-disable-next-line no-console -- mount misconfiguration must reach the integrator
      console.warn(`[Omniguide] Category guide: nothing to observe. Tried: ${describeObserveTarget(config.plpWidget?.mount, config.plpWidget?.selector, '[data-omniguide-plp], #category-recommendations-root')}. Not loading.`);
    }
    if (plpObserveEl) {
      const loadMode = config.plpWidget?.loadMode ?? 'visible';
      if (loadMode === 'immediate') {
        mountCategoryGuide(config, base);
      } else {
        const io = observeVisibility(plpObserveEl, config.plpWidget?.rootMargin ?? '600px', () => {
          mountCategoryGuide(config, base);
        });
        observers.push(io);
      }
    }
  }

  const instance: OmniguideInstance = {
    search: null, // Set lazily when search chunk loads
    productFit: null,
    categoryGuide: null,
    openSearch: (query?: string) => handleOpenSearch(query ?? '', 'api', base),
    destroy() {
      triggerResult?.destroy();
      searchIntegration?.destroy();
      productFitIntegration?.destroy();
      categoryGuideIntegration?.destroy();
      for (const io of observers) io.disconnect();
      document.getElementById('omniguide-token-overrides')?.remove();

      // Reset state
      searchIntegration = null;
      searchChunkPromise = null;
      productFitIntegration = null;
      categoryGuideIntegration = null;
      triggerResult = null;
      currentConfig = null;
    },
  };

  return instance;
}

/**
 * Same contract as the UMD entry's `start`: DOM-ready → experiment arm →
 * `init()` or `null`. Bound to THIS entry's lazy `init`.
 */
export const start: (config: BundleInitConfig) => Promise<OmniguideInstance | null> = createStart(init);

/**
 * Get the bundle version.
 */
export function getVersion(): string {
  return typeof __OMNIGUIDE_VERSION__ !== 'undefined' ? __OMNIGUIDE_VERSION__ : 'unknown';
}

// ── Global exposure ──────────────────────────────────────────────

// ── Preview mode console API ─────────────────────────────────────────

function setPreviewApi(url: string): void {
  setPreviewApiUrl(url);
  // eslint-disable-next-line no-console -- intentional user-visible feedback from Omniguide.setPreviewApi() call
  console.info(`[Omniguide] Preview API set to ${url}. Reload the page for changes to take effect.`);
}

function clearPreviewApi(): void {
  clearPreviewApiUrl();
  // eslint-disable-next-line no-console -- intentional user-visible feedback from Omniguide.clearPreviewApi() call
  console.info('[Omniguide] Preview API cleared. Reload the page to use the default API.');
}

// ── Global exposure ──────────────────────────────────────────────

if (typeof window !== 'undefined') {
  (window as unknown as Record<string, unknown>)['Omniguide'] = {
    init,
    start,
    getVersion,
    setPreviewApi,
    clearPreviewApi,
    isPreviewMode,
    // Reachable from a storefront console so a wiring audit does not have to
    // click a product and watch for the warning. Reports 'unknown' until a
    // feature actually mounts — on this entry they mount lazily.
    getAnalyticsAdapterHealth,
  };
}

// ── Declarative auto-init ────────────────────────────────────────

function declarativeInit(): void {
  const scripts = document.querySelectorAll('script[data-omniguide-config]');
  scripts.forEach((script) => {
    const raw = script.getAttribute('data-omniguide-config');
    if (!raw) return;
    try {
      const config = JSON.parse(raw) as BundleInitConfig;
      init(config);
    } catch (e) {
      // eslint-disable-next-line no-console -- surface declarative-init JSON parse failure at top-level loader
      console.error('[Omniguide] Failed to parse data-omniguide-config:', e);
    }
  });
}

if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', declarativeInit);
  } else {
    declarativeInit();
  }
}
