/**
 * The slice of PostHog's browser API this bundle touches.
 *
 * Deliberately NOT a dependency on `posthog-js`. The storefront loads PostHog
 * itself, from its own snippet, on its own schedule — the SDK only ever reads
 * `window.posthog` if it happens to be there. Typing it as an interface of
 * optional methods keeps that honest: every call site has to check before it
 * calls, which is exactly the fail-open posture the experiment gate needs.
 *
 * Every method is optional because a half-initialised PostHog is a real state:
 * the snippet installs a stub array-shim first and swaps in the real library
 * when the script lands, so `window.posthog` can exist with `capture` present
 * and `onFeatureFlags` missing.
 */
export interface PostHogLike {
  /** Resolve a flag to its variant string, `true`/`false`, or `undefined`. */
  getFeatureFlag?: (key: string) => unknown;
  /** Fires once flags have been fetched (and again on every later refresh). */
  onFeatureFlags?: (callback: () => void) => void;
  /** Attach super-properties to every subsequent capture. */
  register?: (properties: Record<string, unknown>) => void;
  /** Send an event. */
  capture?: (eventName: string, properties?: Record<string, unknown>) => void;
}

/**
 * Read `window.posthog`, or null.
 *
 * Returns null rather than throwing on any shape that is not an object, so a
 * caller never has to guard twice. A storefront that has set
 * `window.posthog = false` to disable it (a documented PostHog pattern) lands
 * here as "absent", which is the correct reading.
 */
export function getPostHog(): PostHogLike | null {
  if (typeof window === 'undefined') return null;
  try {
    const candidate = (window as unknown as Record<string, unknown>)['posthog'];
    if (!candidate || typeof candidate !== 'object') return null;
    return candidate as PostHogLike;
  } catch {
    // A property getter on window can throw (extensions do this). Absent.
    return null;
  }
}
