/**
 * Observability for the host theme's analytics adapter.
 *
 * The adapter is the ONLY route to 3rd-party analytics: nothing the SDK sends
 * reaches PostHog or the dataLayer without it. What an unwired host loses is
 * therefore the adapter copy of every click, not the click itself — the search,
 * product-fit and category-guide click handlers each also fire a backend leg
 * (`rec_product_clicked`), so a `session_event` row still lands.
 *
 * The two copies are not equivalent, which is why the loss is worth a signal.
 * The backend leg does record what the shopper was looking for on the
 * conversational surfaces: a click out of search (`chat_result`) and an inline
 * link in an answer (`chat_msg`) both send `query_context` alongside
 * `rec_product_clicked` (SOI-2373). A `product_fit` or `category_guide` click
 * sends no query on either leg, because neither surface has a shopper query to
 * record.
 *
 * What the adapter copy still holds alone is the journey metrics attached to
 * the click (`time_in_conversation_sec`, `has_clicked_product`): those ride
 * `buildAnalyticsProperties`, which is only ever handed to the adapter call and
 * never to the backend write. So an unwired host loses how long the shopper had
 * been looking, not what they were looking for. Attribution reporting built on
 * the 3rd-party tool simply has no row at all.
 *
 * That loss used to be reported only behind a debug localStorage flag, which
 * made an unwired storefront indistinguishable from a healthy one in production.
 * So the signal here is deliberately NOT debug-gated.
 *
 * Each distinct fault is reported at most once per page load. `track()` sits in
 * a hot path that runs on every click, and a line per click would be its own
 * bug — but the latch is per fault kind rather than global, so an adapter that
 * throws is never silenced just because a different fault reported first.
 */

import { createScopedLogger } from '../logger.js';
import type { AnalyticsAdapter } from '../types.js';

const log = createScopedLogger('analyticsAdapter');

/** Why the adapter could not deliver: never configured, wrong shape, or it threw. */
export type AnalyticsAdapterFault = 'missing' | 'invalid' | 'threw';

export interface AnalyticsAdapterHealth {
  /** 'unknown' until the hook mounts; 'ok' once a usable adapter is seen. */
  status: 'unknown' | 'ok' | AnalyticsAdapterFault;
  /** The event that first hit the fault, when a click rather than mount found it. */
  eventName?: string;
}

const FAULT_REASON: Record<AnalyticsAdapterFault, string> = {
  missing: 'no analyticsAdapter is configured',
  invalid: 'config.analyticsAdapter has no track() function',
  threw: 'config.analyticsAdapter.track() threw',
};

// A missing or malformed adapter is never called, so nothing it would have sent
// arrives. A throwing one IS called: a host callback that forwards to several
// destinations can deliver to one and then raise on the next, so the honest
// claim is incomplete delivery, not total loss. An operator reads these lines
// and acts on them, so they must not overstate in either direction.
const FAULT_HEADLINE: Record<AnalyticsAdapterFault, string> = {
  missing: 'Click analytics are not reaching 3rd-party analytics',
  invalid: 'Click analytics are not reaching 3rd-party analytics',
  threw: 'Click analytics may be reaching 3rd-party analytics only in part',
};

const FAULT_EVENT_LABEL: Record<AnalyticsAdapterFault, string> = {
  missing: 'First dropped event',
  invalid: 'First dropped event',
  threw: 'First affected event',
};

const FAULT_GUIDANCE: Record<AnalyticsAdapterFault, string> = {
  // Declarative init is a JSON attribute, so it cannot carry a function at all:
  // a storefront set up that way always lands here, and the only way to deliver
  // click analytics is to initialise with a config object instead.
  missing: 'Pass config.analyticsAdapter to Omniguide.init() — a declarative'
    + ' data-omniguide-config is JSON and cannot carry a function.',
  invalid: 'config.analyticsAdapter must be an object with a track(name, props) function.',
  threw: 'Whatever the callback sent before raising did arrive; anything after it'
    + ' did not. Delivery stays partial until the host callback is fixed.',
};

interface SharedHealthState {
  health: AnalyticsAdapterHealth;
  reportedFaults: Set<AnalyticsAdapterFault>;
}

/**
 * PAGE scope, not module scope.
 *
 * Module scope already covered the ordinary case: search, product-fit and
 * category-guide each mount the hook, and one unwired theme must not report
 * three times. It did NOT cover two SDK artifacts on one page (UMD alongside
 * ESM mid-migration), which get a module copy each. That split made the latch
 * lie in the one direction that matters: each copy keeps its own status, so
 * whichever entry last assigned `window.Omniguide` answers the audit, and it
 * can answer `ok` while the other copy has already recorded dropped events.
 *
 * Hanging the state off `globalThis` gives every copy on the page one latch, so
 * "first fault wins" holds across artifacts rather than only within one bundle.
 */
const SHARED_STATE_KEY = '__omniguideAnalyticsAdapterHealth__';

function state(): SharedHealthState {
  const container = globalThis as unknown as Record<string, SharedHealthState | undefined>;
  let shared = container[SHARED_STATE_KEY];
  if (!shared) {
    shared = { health: { status: 'unknown' }, reportedFaults: new Set<AnalyticsAdapterFault>() };
    container[SHARED_STATE_KEY] = shared;
  }
  return shared;
}

/**
 * First fault wins. A later fault must not overwrite the one an audit needs,
 * and a mount-time check — which has no event name — must not erase the event
 * name a click already recorded.
 */
function recordFault(fault: AnalyticsAdapterFault, eventName?: string): void {
  const s = state();
  if (s.health.status === 'unknown' || s.health.status === 'ok') {
    s.health = eventName ? { status: fault, eventName } : { status: fault };
    return;
  }
  if (eventName && !s.health.eventName) s.health = { ...s.health, eventName };
}

function reportFault(fault: AnalyticsAdapterFault, eventName?: string, error?: unknown): void {
  recordFault(fault, eventName);
  if (state().reportedFaults.has(fault)) return;
  state().reportedFaults.add(fault);
  const first = eventName ? ` ${FAULT_EVENT_LABEL[fault]}: "${eventName}".` : '';
  const message = `${FAULT_HEADLINE[fault]} — ${FAULT_REASON[fault]}.`
    + ` ${FAULT_GUIDANCE[fault]}${first}`;
  // A throwing host callback is an exception the SDK swallowed; it carries a
  // cause worth a stack, and it used to surface as an uncaught error.
  if (fault === 'threw') log.error(message, error);
  else log.warn(message);
}

/**
 * True when the adapter can be called. Reports the fault once when it cannot.
 * Called on mount so an audit sees the signal on page load without clicking,
 * and again from the delivery path so an adapter wired later is still delivered
 * to — though a fault already recorded is not retracted.
 */
export function checkAnalyticsAdapter(
  adapter: AnalyticsAdapter | undefined,
  eventName?: string,
): adapter is AnalyticsAdapter {
  if (!adapter) {
    reportFault('missing', eventName);
    return false;
  }
  if (typeof adapter.track !== 'function') {
    reportFault('invalid', eventName);
    return false;
  }
  // Never downgrades a recorded fault: one integration wired correctly does not
  // undo another one that is not, and an audit reading this must not see 'ok'
  // while telemetry is being dropped.
  if (state().health.status === 'unknown') state().health = { status: 'ok' };
  return true;
}

/** Report an adapter that accepted the call but threw while handling it. */
export function reportAnalyticsAdapterThrew(eventName: string, error: unknown): void {
  reportFault('threw', eventName, error);
}

/**
 * Current delivery health, for auditing a storefront from the browser console
 * (`Omniguide.getAnalyticsAdapterHealth()`) without having to click something.
 */
export function getAnalyticsAdapterHealth(): AnalyticsAdapterHealth {
  return { ...state().health };
}

/** Test seam — faults report once per page load, so suites must reset them. */
export function _resetAnalyticsAdapterHealth(): void {
  state().health = { status: 'unknown' };
  state().reportedFaults.clear();
}
