/**
 * eCommerce analytics forwarder — `window.dataLayer` → the analytics adapter.
 *
 * A storefront's GA4 dataLayer already carries the only events anyone wants to
 * see next to the SDK's own: `view_item`, `add_to_cart`, `purchase`. Getting
 * them into the host's product analytics under readable names was ~90 lines of
 * hand-written `<script>` on every store that wanted it. This is that script,
 * with its three sharp edges fixed.
 *
 * ── Where this is NOT the dataLayer bridge ──────────────────────────
 *
 * `omniguide-core`'s `datalayer-bridge.ts` also polls `window.dataLayer` when
 * `dataLayerBridge.gtm` is on, and the two CANNOT double-count, because they
 * do not share a destination:
 *
 *   bridge     window.dataLayer ──► EventService ──► the Omniguide backend
 *   forwarder  window.dataLayer ──► AnalyticsAdapter ──► the host's analytics
 *
 * Neither writes to the other's sink, and neither writes back into
 * `window.dataLayer`, so there is no path by which one's output becomes the
 * other's input. Running both on one page sends each storefront event to each
 * destination exactly once — which is the point: the backend needs the raw
 * vocabulary, the host's dashboards want the friendly names.
 *
 * The one shape that could close a loop is a HOST adapter that pushes back
 * into `window.dataLayer`. It still cannot: the pushed entry is named with the
 * MAPPED name (`eCommerce Purchase`), and only the map's KEYS (`purchase`) are
 * forwarded, so a round-tripped entry falls out at the allowlist on the very
 * next tick. There is a test pinning that.
 *
 * ── Do not reinvent the SDK-origin skip ─────────────────────────────
 *
 * The SDK's own events reach the host's adapter, and an adapter that pushes to
 * the dataLayer puts them back in the array this forwarder reads. The theme
 * script guarded that with a hardcoded prefix list (`ai_search_`,
 * `product_rec_`, …) — and `datalayer-bridge.ts` documents, at length, that
 * the list had ALREADY drifted past `rec_product_clicked` and
 * `category_rec_*`. So every event the SDK hands an adapter is stamped with
 * `SDK_ORIGIN_MARKER`, precisely so a round-tripped event can be recognised
 * without a name list to maintain. This file uses the marker. It must never
 * grow a prefix list.
 */

import { SDK_ORIGIN_MARKER, logger, stripKeysDeep } from '@swiftotter/omniguide-core';
import type { AnalyticsAdapter } from '@swiftotter/omniguide-core';

export interface EcommerceAnalyticsConfig {
  /** Off switch. Anything but an explicit `false` is on. */
  enabled?: boolean;
  /**
   * `dataLayer event name` → `name to track`. Also the ALLOWLIST: an event
   * absent from the map is never forwarded. Replaces the default map wholly
   * rather than merging, so a store can narrow it.
   */
  eventMap?: Record<string, string>;
  /** How long a `transaction_id` stays deduped. Default 30 days. */
  dedupeTtlMs?: number;
  /** Poll interval for `window.dataLayer`. Default 1000ms. */
  pollIntervalMs?: number;
}

/**
 * GA4's eCommerce vocabulary, renamed for a human reading a dashboard.
 *
 * An allowlist, not a passthrough: `window.dataLayer` also carries GTM
 * lifecycle noise, consent updates and whatever every third-party tag on the
 * page decides to push. Forwarding all of it into the host's product analytics
 * would bury the handful of events that mean something behind hundreds that do
 * not — and bill them for it.
 */
export const DEFAULT_ECOMMERCE_EVENT_MAP: Readonly<Record<string, string>> = Object.freeze({
  purchase: 'eCommerce Purchase',
  add_to_cart: 'eCommerce Add To Cart',
  remove_from_cart: 'eCommerce Remove From Cart',
  begin_checkout: 'eCommerce Begin Checkout',
  view_item: 'eCommerce View Item',
  view_item_list: 'eCommerce View Item List',
  view_cart: 'eCommerce View Cart',
  search: 'eCommerce Search',
  add_to_wishlist: 'eCommerce Add To Wishlist',
});

const DEFAULT_POLL_INTERVAL_MS = 1000;
/** 30 days. An order confirmation page a shopper bookmarks and revisits. */
const DEFAULT_DEDUPE_TTL_MS = 30 * 24 * 60 * 60 * 1000;

/**
 * Base of the localStorage key holding `{ [transaction_id]: firstSeenEpochMs }`.
 *
 * Namespaced per `websiteId` by `purchaseStorageKey`. The key is per ORIGIN,
 * and a single origin can serve several channels on different paths (`/us/`,
 * `/ca/`), each with its own order counter — `readTransactionId` accepts a
 * bare number, so two channels both issuing order `1001` collided and the
 * second store's order was never forwarded at all. That direction is the
 * dangerous one: it SUPPRESSES revenue, so the dashboard is quietly low with
 * no error anywhere to notice.
 */
export const PURCHASE_DEDUPE_STORAGE_KEY = 'omniguide_ecom_purchases';

/** The dedupe store for one website. See `PURCHASE_DEDUPE_STORAGE_KEY`. */
export function purchaseStorageKey(websiteId: string): string {
  return websiteId ? `${PURCHASE_DEDUPE_STORAGE_KEY}:${websiteId}` : PURCHASE_DEDUPE_STORAGE_KEY;
}

/**
 * Keys never forwarded to the host's analytics, AT EVERY DEPTH.
 *
 * The same three the core bridge blocks, stripped by the same walk — see
 * `stripKeysDeep`. A top-level `includes()` was the whole protection here, and
 * `datalayer-bridge.ts:282` documents that a vendor only has to nest to defeat
 * one: `ecommerce.customer.email` and an `actionField` carrying
 * `user_properties` both went through verbatim while the root-level keys of
 * the same names were being removed, and a checkout push carrying the GA4
 * enhanced-conversions block under `ecommerce` is a field-observed shape, not
 * a hypothetical.
 *
 * It IS a privacy boundary, and the earlier note here arguing otherwise was
 * wrong for the configuration this SDK ships: the documented snippet pairs
 * `ecommerceAnalytics` with `analytics: { posthog: true }`, i.e.
 * `window.posthog.capture`. PostHog loads from its own snippet rather than
 * from the GTM container, so a store whose container forwards to GA4 and Meta
 * has never sent these payloads to PostHog — which makes this forwarder
 * exactly the thing that newly introduces them, with no consent gate and no
 * DSAR path once they are there.
 *
 * `SDK_ORIGIN_MARKER` joins them because the forwarder stamps its own, below:
 * a marker arriving on a vendor entry is not ours to pass on.
 */
const IDENTITY_KEYS = ['user_data', 'user_properties', 'customer'] as const;
const DROPPED_KEYS: readonly string[] = [...IDENTITY_KEYS, SDK_ORIGIN_MARKER];

/**
 * Most entries forwarded in one tick, and most elements read from the array.
 *
 * The core bridge carries both bounds over the same `window.dataLayer`, with
 * `MAX_ARRAY_ITEMS` documented as "the bound that keeps a hostile length from
 * being a page freeze". This file reimplemented the same poll and shipped
 * neither. `length` is vendor-controlled — an array Proxy can report any
 * number it likes — and the first tick runs SYNCHRONOUSLY inside `init()`, so
 * an unbounded walk locks the tab before the page finishes loading.
 */
const MAX_FORWARDS_PER_TICK = 50;
const MAX_ARRAY_ITEMS = 1000;

/**
 * Read a key without trusting the object.
 *
 * These are vendor objects — Proxies and throwing getters both occur in the
 * wild (GTM's own `eventCallback`, consent shims). A throw must degrade one
 * field, not kill the poll for every later entry.
 */
function safeRead(source: Record<string, unknown>, key: string): unknown {
  try {
    return source[key];
  } catch {
    return undefined;
  }
}

/**
 * Module-level, like the core bridge's, and for the same reason.
 *
 * `init()` is callable more than once on a page. Per-start state in a closure
 * would mean a second `init()` re-forwards the entire array — a duplicate of
 * every eCommerce event the page has seen so far, including the purchase.
 */
let forwarded = new WeakSet<object>();
let pollTimer: ReturnType<typeof setInterval> | null = null;
/** Which website the running poller belongs to — see `startEcommerceAnalytics`. */
let runningWebsiteId = '';

/** Test seam: forget every forwarded entry and stop the poller. */
export function _resetEcommerceAnalytics(): void {
  if (pollTimer !== null) {
    clearInterval(pollTimer);
    pollTimer = null;
  }
  runningWebsiteId = '';
  forwarded = new WeakSet<object>();
}

function readSeenPurchases(storageKey: string): Record<string, number> {
  try {
    const raw = window.localStorage.getItem(storageKey);
    if (!raw) return {};
    const parsed: unknown = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return {};
    return parsed as Record<string, number>;
  } catch {
    // Blocked storage, private mode, or a corrupt value someone else wrote.
    // "Nothing seen yet" forwards the purchase — a duplicate row beats a lost
    // order.
    return {};
  }
}

function writeSeenPurchases(storageKey: string, seen: Record<string, number>): void {
  try {
    window.localStorage.setItem(storageKey, JSON.stringify(seen));
  } catch {
    // Quota or blocked storage. The dedupe degrades to per-page-load, which is
    // what it was before this existed.
  }
}

/**
 * Drop entries older than the TTL.
 *
 * Run on every write rather than at random. A shopper records at most a
 * handful of orders, so the walk is trivial, and "occasionally" is the kind of
 * behaviour that cannot be tested without either stubbing `Math.random` or
 * accepting a flaky test.
 */
function prune(seen: Record<string, number>, now: number, ttlMs: number): Record<string, number> {
  const kept: Record<string, number> = {};
  for (const [id, at] of Object.entries(seen)) {
    if (typeof at === 'number' && now - at < ttlMs) kept[id] = at;
  }
  return kept;
}

/** GA4 puts it at the root; GTM's `ecommerce` wrapper puts it one level down. */
function readTransactionId(entry: Record<string, unknown>): string | null {
  const candidates: unknown[] = [safeRead(entry, 'transaction_id')];
  const ecommerce = safeRead(entry, 'ecommerce');
  if (ecommerce && typeof ecommerce === 'object') {
    candidates.push(safeRead(ecommerce as Record<string, unknown>, 'transaction_id'));
  }
  for (const candidate of candidates) {
    if (typeof candidate === 'string' && candidate) return candidate;
    if (typeof candidate === 'number' && Number.isFinite(candidate)) return String(candidate);
  }
  return null;
}

/**
 * Claim a purchase, across page loads.
 *
 * `purchase` is the one event where a duplicate is not a redundant row: it
 * carries revenue, so a second copy inflates the number the business reads.
 * An order confirmation page is reloaded, bookmarked, back-buttoned into and
 * emailed to the shopper, and every one of those re-fires the dataLayer push —
 * which is why the record has to outlive the page, in storage.
 *
 * A purchase with NO transaction id is forwarded: there is nothing to dedupe
 * on, and dropping it would lose the event entirely.
 */
function claimPurchase(entry: Record<string, unknown>, ttlMs: number, storageKey: string): boolean {
  const transactionId = readTransactionId(entry);
  if (!transactionId) return true;

  const now = Date.now();
  const seen = readSeenPurchases(storageKey);
  const firstSeen = seen[transactionId];
  if (typeof firstSeen === 'number' && now - firstSeen < ttlMs) return false;

  const next = prune(seen, now, ttlMs);
  next[transactionId] = now;
  writeSeenPurchases(storageKey, next);
  return true;
}

/**
 * The entry, minus its routing key and the identity keys at every depth.
 *
 * The walk is core's — `stripKeysDeep` — rather than a second implementation
 * here. It rebuilds containers instead of mutating the vendor's live object,
 * guards every key read, drops DOM nodes, and is bounded in depth, node count
 * and array length. A local copy would be a weaker version of all of that over
 * the same array, which is how the shallow strip got here.
 *
 * `event` is the routing key and is removed at the ROOT ONLY. It is not in
 * `DROPPED_KEYS` because a deeper `event` belongs to the vendor's own payload
 * shape, and dropping it would silently remove a field the store pushed.
 */
function toProperties(entry: Record<string, unknown>): Record<string, unknown> {
  const properties = stripKeysDeep(entry, DROPPED_KEYS);
  delete properties['event'];
  return properties;
}

/**
 * A bounded COPY of the array, read once.
 *
 * `for…of` over `window.dataLayer` takes a LIVE iterator, so an adapter that
 * pushes back into the array is visited by the very pass that created the
 * entry. With the default map that terminates after one hop (the echo carries
 * the mapped name, which is not a map key) — but `eventMap` is a public knob
 * documented as replacing the default map wholly, and the moment any mapped
 * value is also a key, nothing breaks the cycle: the first tick runs
 * synchronously inside `init()`, so the tab locks before the page loads. A
 * snapshot ends the pass where it started; the marker stamped on what this
 * forwarder emits is what stops the echo on the NEXT tick as well.
 */
function snapshot(dataLayer: unknown[]): unknown[] {
  let length = 0;
  try {
    // `Number(...)` forces one conversion of a length a Proxy can otherwise
    // grow on every read — a snapshot in name only. Infinity and NaN are
    // rejected rather than trusted; see core's identical guard.
    const raw = Number(dataLayer.length);
    if (!Number.isFinite(raw) || raw < 0) return [];
    length = Math.min(Math.floor(raw), MAX_ARRAY_ITEMS);
  } catch {
    return [];
  }
  const items: unknown[] = [];
  for (let i = 0; i < length; i++) {
    // Indexed with a per-element guard: one throwing index must not take the
    // whole tick, and with it every entry behind it.
    try {
      items.push(dataLayer[i]);
    } catch {
      items.push(undefined);
    }
  }
  return items;
}

function drain(
  adapter: AnalyticsAdapter,
  eventMap: Record<string, string>,
  ttlMs: number,
  storageKey: string,
): void {
  let dataLayer: unknown;
  try {
    dataLayer = (window as unknown as Record<string, unknown>)['dataLayer'];
  } catch {
    return;
  }
  if (!Array.isArray(dataLayer)) return;

  let budget = MAX_FORWARDS_PER_TICK;

  // Rescan the whole array each tick and track progress by entry IDENTITY, not
  // by an index. A vendor owns this array: it can clear and refill it to the
  // same length, swap in a copy, or splice an entry out, and every one of
  // those breaks a length cursor — in the `purchase` case, by re-forwarding
  // it. See the long version in core's datalayer-bridge.ts.
  for (const entry of snapshot(dataLayer)) {
    // Checked BEFORE the entry is marked, so the remainder of a capped tick
    // stays unseen and is forwarded on the next one rather than discarded.
    if (budget <= 0) return;
    if (!entry || typeof entry !== 'object') continue;
    if (forwarded.has(entry as object)) continue;
    // Marked BEFORE the decision, so an entry rejected below is not
    // reconsidered on every subsequent tick for the life of the page.
    forwarded.add(entry as object);

    const record = entry as Record<string, unknown>;

    // The SDK's own events, round-tripped through a dataLayer-writing adapter.
    // A marker, never a name-prefix list — see the file header.
    if (safeRead(record, SDK_ORIGIN_MARKER)) continue;

    const name = safeRead(record, 'event');
    if (typeof name !== 'string' || !name) continue;

    const mapped = eventMap[name];
    if (!mapped) continue;

    if (name === 'purchase' && !claimPurchase(record, ttlMs, storageKey)) continue;

    // Charged BEFORE the call, like core's: an entry whose adapter threw still
    // consumed an attempt, and leaving it free lets one tick blow past the cap.
    budget--;

    try {
      // The marker is stamped AFTER the spread so nothing in the payload can
      // clear it — the same ordering `useAnalyticsTracking` uses. This is what
      // makes an echo from a dataLayer-writing adapter recognisable by MARKER
      // rather than by the luck of the mapped name not being a map key, which
      // is the mechanism this file's header insists on and the only thing that
      // terminates a custom `eventMap` whose value is also a key.
      adapter.track(mapped, { ...toProperties(record), [SDK_ORIGIN_MARKER]: true });
    } catch (error) {
      // The documented adapter contract is that `track` never throws. The
      // `catch` is not about the interval — an uncaught throw in a
      // `setInterval` callback does NOT stop the interval — it is about the
      // REST OF THIS TICK: entries are added to `forwarded` before `track`
      // runs, so every entry behind a throwing one would be marked seen and
      // never retried.
      logger.warn('analytics adapter threw while forwarding an eCommerce event:', error);
    }
  }
}

/**
 * Start forwarding. Returns a detach.
 *
 * Idempotent: a second call while a poller is already running keeps the first
 * one rather than opening a rival that would double-send every entry. The
 * first tick runs SYNCHRONOUSLY, so entries the storefront pushed before the
 * SDK loaded are not left sitting for a poll interval (or lost, if the page is
 * closed inside it).
 */
export function startEcommerceAnalytics(
  adapter: AnalyticsAdapter,
  config: EcommerceAnalyticsConfig = {},
  websiteId = '',
): () => void {
  if (config.enabled === false) return () => {};
  if (typeof window === 'undefined') return () => {};
  if (pollTimer !== null) {
    // `warn` when it is a DIFFERENT store: the poller and its adapter belong
    // to whichever `init()` ran first, so a second website's events go
    // nowhere, and at `debug` that is invisible in production. Same store,
    // second `init()` is the ordinary idempotent case and stays quiet.
    if (websiteId !== runningWebsiteId) {
      logger.warn(
        `eCommerce analytics is already running for "${runningWebsiteId}"; `
        + `events for "${websiteId}" will NOT be forwarded. One page can forward for one website.`,
      );
    } else {
      logger.debug('eCommerce analytics forwarder is already running; keeping the existing poller.');
    }
    return () => {};
  }

  const eventMap = config.eventMap ?? (DEFAULT_ECOMMERCE_EVENT_MAP as Record<string, string>);
  const ttlMs = config.dedupeTtlMs ?? DEFAULT_DEDUPE_TTL_MS;
  const pollIntervalMs = config.pollIntervalMs ?? DEFAULT_POLL_INTERVAL_MS;
  const storageKey = purchaseStorageKey(websiteId);
  runningWebsiteId = websiteId;

  const tick = (): void => { drain(adapter, eventMap, ttlMs, storageKey); };
  tick();
  pollTimer = setInterval(tick, pollIntervalMs);

  return () => {
    if (pollTimer !== null) {
      clearInterval(pollTimer);
      pollTimer = null;
      runningWebsiteId = '';
    }
  };
}
